        val c = run("ip_count", "top" to "5", "text" to "203.0.113.9 a\n203.0.113.9 b\n198.51.100.7 c\n203.0.113.9 d\nno ip here").rows()
        assertEquals(listOf("1", "203.0.113.9", "3", "75.0%"), c[0]); assertEquals("198.51.100.7", c[1][1])
