        for ((plain, enc) in v) { assertEquals(enc, Base32.encode(plain.toByteArray())); assertEquals(plain, String(Base32.decode(enc)!!)) }
        assertEquals("foobar", String(Base32.decode("mzxw 6ytb-oi")!!)); assertEquals(null, Base32.decode("MZXW1"))
        assertEquals("MZXW6YTBOI======", run("base32_encode", "t" to "foobar").block()[0])
        assertEquals("foobar", run("base32_decode", "t" to "MZXW6YTBOI======").block()[0])
    }

    @Test fun percentAndHtmlAndBase64() {
