        assertEquals("한글 a+b", Percent.decode("%ED%95%9C%EA%B8%80%20a+b")); assertEquals("한글 a b", Percent.decode("%ED%95%9C%EA%B8%80%20a+b", true)); assertEquals(null, Percent.decode("100%")); assertEquals(null, Percent.decode("%zz"))
        assertEquals("%ED%95%9C", run("url_encode", "mode" to "%20 (주소·경로)", "t" to "한").block()[0]); assertEquals("한 글", run("url_decode", "mode" to "공백으로 (폼 데이터)", "t" to "%ED%95%9C+%EA%B8%80").block()[0])
        assertEquals("&lt;a href=&quot;x&quot;&gt;내 &amp; 네 &#39;q&#39;&lt;/a&gt;", Html.encode("<a href=\"x\">내 & 네 'q'</a>")); assertEquals("&#xD55C;", Html.encode("한", true))
        assertEquals("<b>안녕</b> & © 'hi' 😀", Html.decode("&lt;b&gt;안녕&lt;/b&gt; &amp; &copy; &#39;hi&#39; &#x1F600;")); assertEquals("&unknown; &#xZZ;", Html.decode("&unknown; &#xZZ;"))
        assertEquals("7JWI64WV7ZWY7IS47JqUIGhlbGxvICYg5LiW55WM", run("base64_encode", "mode" to "표준", "t" to "안녕하세요 hello & 世界").block()[0])
        assertEquals("안녕하세요 hello & 世界", run("base64_decode", "t" to "7JWI64WV7ZWY7IS47JqUIGhlbGxvICYg5LiW55WM").block()[0])
        assertEquals("안녕하세요 hello & 世界", run("base64_decode", "t" to "7JWI64WV7ZWY7IS47JqUIGhlbGxvICYg5LiW55WM".trimEnd('=').chunked(10).joinToString("\n")).block()[0])  // 줄바꿈 OK
        assertEquals("subjects?_d", String(java.util.Base64.getUrlDecoder().decode(run("base64_encode", "mode" to "URL 안전·패딩 없음", "t" to "subjects?_d").block()[0])))
        assertTrue(run("base64_decode", "t" to "!!!").hasError)
    }

    @Test fun hexAndBaseAndEpochAndUnits() {
        assertEquals("48 65 6c 6c 6f", run("hex_encode", "sep" to "공백", "t" to "Hello").block()[0]); assertEquals("한글", run("hex_decode", "t" to "ED 95 9C EA B8 80").block()[0]); assertTrue(run("hex_decode", "t" to "abc").hasError)
        val b = run("base_convert", "from" to "10", "n" to "3232235521")
        assertEquals("C0A80001", b.kv("16진수")); assertEquals("1100 0000 1010 1000 0000 0000 0000 0001", b.kv("2진수")); assertEquals("2FQ2P1", run("base_convert", "from" to "36", "n" to "2fq2p1").kv("36진수"))
        val e = run("epoch_convert", "tz" to "한국 KST", "v" to "1700000000")
        assertEquals("2023-11-14 22:13:20 (UTC)", e.kv("UTC")); assertEquals("2023-11-15 07:13:20 (Asia/Seoul)", e.kv("한국(KST)")); assertEquals("초", e.kv("입력 단위"))
        assertEquals("밀리초", run("epoch_convert", "tz" to "UTC", "v" to "1700000000123").kv("입력 단위"))
        assertEquals("1700000000", run("epoch_convert", "tz" to "한국 KST", "v" to "2023-11-15 07:13:20").kv("초")); assertEquals("1700000000", run("epoch_convert", "tz" to "UTC", "v" to "2023-11-14T22:13:20Z").kv("초"))
        assertEquals("1700000000", run("epoch_convert", "tz" to "UTC", "v" to "2023-11-14T22:13:20+00:00").kv("초")); assertTrue(run("epoch_convert", "tz" to "UTC", "v" to "어제").hasError)
        assertEquals("62.5", run("unit_rate", "v" to "500", "u" to "Mbps").kv("MB/s")); assertEquals("1.073741824", run("unit_bytes", "v" to "1", "u" to "GiB").kv("GB")); assertEquals("1024", run("unit_bytes", "v" to "1", "u" to "KiB").kv("B"))
    }

    @Test fun punycodeAndUrlParsing() {
        assertEquals("xn--bj0bj06e.kr", run("punycode_encode", "d" to "한글.kr").kv("퓨니코드")); assertEquals("xn--vv4b11d.xn--3e0b707e", run("punycode_encode", "d" to "예시.한국").kv("퓨니코드"))
        assertEquals("한글.kr", run("punycode_decode", "d" to "xn--bj0bj06e.kr").kv("원래 글자"))
        assertTrue("키릴 a 가 섞이면 경고", run("punycode_encode", "d" to "аpple.com").text().contains("피싱")); assertFalse(run("punycode_encode", "d" to "한글.kr").text().contains("피싱"))
        val u = run("url_parse", "u" to "https://login.example.com@203.0.113.9:8443/a/b?next=%2Fhome&x=1#top")
        assertEquals("https", u.kv("스킴")); assertEquals("login.example.com", u.kv("사용자 정보")); assertEquals("203.0.113.9", u.kv("호스트")); assertEquals("8443", u.kv("포트")); assertEquals("/a/b", u.kv("경로")); assertEquals("/home", u.kv("next"))
        assertTrue(u.text().contains("'@'")); assertTrue(u.text().contains("IP 주소예요"))
        assertTrue(run("url_parse", "u" to "http://3232235521/login").text().contains("숫자")); assertTrue(run("url_parse", "u" to "https://www.example.com/path?q=1").text().contains("눈에 띄는 속임수 신호는 없어요"))
        assertTrue(run("url_parse", "u" to "example.com/x").text().contains("http:// 를 붙여")); assertEquals("443 (기본)", run("url_parse", "u" to "https://example.com").kv("포트"))
        val q = run("query_parse", "q" to "https://x.com/s?q=%ED%95%9C+test&lang=ko&lang=en").rows()
        assertEquals(listOf(listOf("q", "한 test"), listOf("lang", "ko"), listOf("lang", "en")), q)
        assertEquals("https://example.com/search?q=%ED%95%9C%EA%B8%80%20%EA%B2%80%EC%83%89&lang=ko", run("query_build", "base" to "https://example.com/search", "kv" to "q=한글 검색\nlang=ko").block()[0])
        assertTrue(run("hostname_check", "h" to "my-server.example.com").text().contains("규칙에 맞는")); assertTrue(run("hostname_check", "h" to "my_server.example.com").text().contains("밑줄")); assertTrue(run("hostname_check", "h" to "-bad-.com").hasError || run("hostname_check", "h" to "-bad-.com").text().contains("하이픈"))
    }

    // ---------------------------------------------------------------- 해시·토큰
    @Test fun hashesMatchKnownValues() {
        assertEquals("d41d8cd98f00b204e9800998ecf8427e", Hashes.hex(Hashes.digest("MD5", ByteArray(0)))); assertEquals("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad", Hashes.hex(Hashes.digest("SHA-256", "abc".toByteArray())))
        assertEquals("aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d", run("hash_text", "alg" to "SHA-1", "t" to "hello").kv("16진수")); assertEquals(5, run("hash_all", "t" to "x").rows().size.let { run("hash_all", "t" to "x").outs.size })
        assertEquals("5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843", run("hmac_text", "alg" to "HmacSHA256", "k" to "Jefe", "t" to "what do ya want for nothing?").kv("16진수"))
        assertEquals("de7c9b85b8b78aa6bc8a7a36f70a90701c9db4d9", run("hmac_text", "alg" to "HmacSHA1", "k" to "key", "t" to "The quick brown fox jumps over the lazy dog").kv("16진수"))
        assertTrue(run("hash_text", "alg" to "MD5", "t" to "x").text().contains("충돌"))
    }

    @Test fun totpMatchesRfc6238() {
        val k1 = "12345678901234567890".toByteArray(); val k256 = "12345678901234567890123456789012".toByteArray()
        assertEquals("94287082", Totp.at(k1, 59, 30, 8, "HmacSHA1")); assertEquals("07081804", Totp.at(k1, 1111111109, 30, 8, "HmacSHA1")); assertEquals("46119246", Totp.at(k256, 59, 30, 8, "HmacSHA256"))
        assertEquals("287082", Totp.at(k1, 59, 30, 6, "HmacSHA1"))
        val r = run("totp_code", "s" to Base32.encode(k1), "d" to "6", "p" to "30", "a" to "SHA1", "t" to "59")
        assertEquals("287082", r.kv("지금 코드")); assertEquals("1초", r.kv("남은 시간")); assertTrue(run("totp_code", "s" to "1!", "d" to "6", "p" to "30", "a" to "SHA1", "t" to "").hasError)
    }

    @Test fun checksumsAndTokens() {
        val c = run("crc_checksum", "mode" to "글자(UTF-8)", "t" to "123456789")
        assertEquals("cbf43926", c.kv("CRC-32")); assertEquals("e3069283", c.kv("CRC-32C (iSCSI·SCTP)"))
        assertEquals("11e60398", run("crc_checksum", "mode" to "글자(UTF-8)", "t" to "Wikipedia").kv("Adler-32"))
        assertEquals("220d", run("crc_checksum", "mode" to "16진수 바이트", "t" to "00 01 f2 03 f4 f5 f6 f7").kv("인터넷 체크섬"))   // RFC 1071 예
        val u = run("uuid_gen", "n" to "5", "fmt" to "대문자").block(); assertEquals(5, u.size); assertTrue(u.all { Regex("[0-9A-F]{8}-[0-9A-F]{4}-4[0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12}").matches(it) }); assertEquals(5, u.toSet().size)
        val t = run("token_gen", "fmt" to "16진수", "len" to "32", "n" to "3").block(); assertEquals(3, t.size); assertTrue(t.all { it.length == 64 && it.all { c -> c in "0123456789abcdef" } }); assertEquals(3, t.toSet().size)
        assertTrue(run("token_gen", "fmt" to "영문+숫자", "len" to "24", "n" to "1").block()[0].let { it.length == 24 && it.all { c -> c.isLetterOrDigit() } })
        assertTrue(run("token_gen", "fmt" to "Base64URL", "len" to "16", "n" to "1").block()[0].let { it.length == 22 && it.all { c -> c.isLetterOrDigit() || c == '-' || c == '_' } })
    }

    @Test fun jwtAndBasicAuthAndCert() {
        val ok = run("jwt_decode", "t" to "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjQxMDI0NDQ4MDB9.sig")
        assertTrue(ok.text().contains("John Doe")); assertEquals("HS256", ok.kv("알고리즘")); assertTrue(ok.kv("만료(exp)").contains("후 만료")); assertTrue(ok.kv("발급(iat)").startsWith("2018-01-18"))
        val bad = run("jwt_decode", "t" to "eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0.eyJzdWIiOiJ4IiwiZXhwIjoxMDAwMDAwMDAwfQ.")
        assertEquals("none", bad.kv("알고리즘")); assertTrue(bad.kv("만료(exp)").contains("이미 만료")); assertTrue(bad.text().contains("위조"))
        assertTrue(run("jwt_decode", "t" to "abc.def").hasError)
        assertEquals("Authorization: Basic YWRtaW46c2VjcmV0", run("basic_auth", "v" to "admin:secret").kv("헤더"))
        val d = run("basic_auth", "v" to "Authorization: Basic YWRtaW46c2VjcmV0"); assertEquals("admin", d.kv("아이디")); assertEquals("secret", d.kv("비밀번호"))
        val cert = run("cert_pem", "pem" to TEST_PEM)
        assertTrue(cert.kv("주체(Subject)").contains("CN=selfcheck.test")); assertTrue(cert.kv("남은 기간").endsWith("일 남음")); assertTrue(cert.kv("공개키").startsWith("RSA 2048"))
        assertTrue(cert.kv("대체 이름(SAN)").contains("selfcheck.test") && cert.kv("대체 이름(SAN)").contains("IP 127.0.0.1")); assertEquals(95, cert.kv("SHA-256 지문").length)
        assertTrue(run("cert_pem", "pem" to "hello").hasError)
    }
